import React, { useState, useRef, useEffect } from "react";
import { attendanceAPI } from "./api_service";

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);

  const [successCount, setSuccessCount] = useState(0);
  const [notRecognizedCount, setNotRecognizedCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false,
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
        }
      } catch (err) {
        setError("Impossible d'accéder à la caméra");
        addNotification("❌ Erreur d'accès caméra", "error");
      }
    };
    startCamera();

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      if (streamRef.current) streamRef.current.getTracks().forEach((t) => t.stop());
    };
  }, [addNotification]);

  useEffect(() => {
    if (!autoMode) {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      return;
    }

    captureIntervalRef.current = setInterval(async () => {
      if (!videoRef.current || isProcessingRef.current) return;

      try {
        const canvas = document.createElement("canvas");
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL("image/jpeg", 0.85);
        const payload = imageBase64.split(",")[1]; // sans préfixe

        isProcessingRef.current = true;
        setFrameCount((prev) => prev + 1);

        const response = await attendanceAPI.recognize(payload);
        const data = response?.data;
        console.log("📥 Réponse backend:", data);

        if (data.success && data.student) {
          setResult({
            success: true,
            name: data.student,
            email: data.email || "N/A",
            confidence: (data.confidence * 100).toFixed(1),
            attendanceId: data.attendance_id,
            timestamp: new Date().toLocaleTimeString(),
            message: `✅ ${data.student} reconnu`,
          });
          setLastDetection(new Date().toLocaleTimeString());
          setSuccessCount((prev) => prev + 1);
          addNotification(`✅ ${data.student} détecté`, "success");
        } else if (data.message === "Visage non reconnu" || !data.success) {
          setResult({
            success: false,
            message: data.message || "Visage non reconnu",
            confidence: ((data.confidence || 0) * 100).toFixed(1),
          });
          setNotRecognizedCount((prev) => prev + 1);
        }
      } catch (err) {
        console.error("[ERROR]", err.response || err);
        setErrorCount((prev) => prev + 1);
        setError(
          `Erreur API - Code: ${err.response?.status || "?"}, Message: ${
            err.response?.data?.message || err.message
          }`
        );
        addNotification(`❌ ${err.message}`, "error");
      } finally {
        isProcessingRef.current = false;
      }
    }, 500);

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    };
  }, [autoMode, addNotification]);

  const stopCamera = () => {
    if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    if (streamRef.current) streamRef.current.getTracks().forEach((t) => t.stop());
    if (videoRef.current) videoRef.current.srcObject = null;
    setAutoMode(false);
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>👤 Reconnaissance Faciale</h1>
      <video ref={videoRef} autoPlay playsInline muted style={{ width: "100%", borderRadius: 8 }} />

      <button onClick={stopCamera}>🛑 Fermer Caméra</button>

      {result && (
        <div style={{ marginTop: 20 }}>
          {result.success ? (
            <>
              <h3 style={{ color: "green" }}>{result.message}</h3>
              <p>Nom: {result.name}</p>
              <p>Email: {result.email}</p>
              <p>Confiance: {result.confidence}%</p>
              <p>ID: {result.attendanceId}</p>
              <p>Heure: {result.timestamp}</p>
            </>
          ) : (
            <>
              <h3 style={{ color: "red" }}>❌ Non reconnu</h3>
              <p>{result.message}</p>
              <p>Confiance: {result.confidence}%</p>
            </>
          )}
        </div>
      )}

      {error && <div style={{ color: "red" }}>{error}</div>}

      <div style={{ marginTop: 20, background: "#eee", padding: 10 }}>
        <p>✅ Succès: {successCount}</p>
        <p>⚠️ Non reconnus: {notRecognizedCount}</p>
        <p>❌ Erreurs API: {errorCount}</p>
        <p>📹 Frames envoyés: {frameCount}</p>
      </div>
    </div>
  );
};

export default CameraRecognition;
